css:
.loader { display: flex; align-items: center; width: var(--loader-size); }
.loader .step { flex: none; width: calc(var(--loader-size) * .13); height: calc(var(--loader-size) * .13); border-radius: 9999px; background: var(--loader-color); opacity: .3; animation: twStep calc(var(--loader-speed) * 3) ease-in-out infinite; }
.loader .step:nth-child(3) { animation-delay: calc(var(--loader-speed) * 1); }
.loader .step:nth-child(5) { animation-delay: calc(var(--loader-speed) * 2); }
.loader .line { position: relative; flex: 1; height: calc(var(--loader-size) * .025); overflow: hidden; background: color-mix(in srgb, var(--loader-color) 22%, transparent); }
.loader .line::after { content: ''; position: absolute; top: 0; bottom: 0; left: 0; right: 0; background: var(--loader-color); transform-origin: left center; animation: twStepLine calc(var(--loader-speed) * 3) ease-in-out infinite; }
.loader .line:nth-child(2)::after { animation-delay: calc(var(--loader-speed) * .3); }
.loader .line:nth-child(4)::after { animation-delay: calc(var(--loader-speed) * 1.3); }
@keyframes twStep { 0%, 20% { opacity: .3; transform: scale(.82); } 30%, 100% { opacity: 1; transform: scale(1); } }
@keyframes twStepLine { 0%, 10% { transform: scaleX(0); } 30%, 100% { transform: scaleX(1); } }
